"""Seam coverage for upstream #902: open BackColor/ForeColor on the cinbase
composition/candidate layer.

Three keys ride the existing per-IME config surface — candidate text color
(``candTextColor``), window background (``windowBackgroundColor``) and the
selection-key color (``selKeyColor``) — all 24-bit ints, ``0`` meaning
"follow the system palette". The house quartet (docs/agents/cinbase-config.md)
is pinned in layers:

* the keys and their defaults exist on ``CinBaseConfig`` even when no JSON
  defines them, and ``sanitize()`` keeps configured values and repairs bad
  ones to the system-palette sentinel;
* all nine shipped ``python/input_methods/*/config/config.json`` carry them,
  because layer 1's ``__dict__.update`` is the only place existing users see
  a new key;
* the engine's ``applyConfig`` puts the values on the ``customizeUI`` reply,
  the same object that already carries ``candFontName`` to the windows
  (PIMEClient.cpp ``updateUI``);
* the settings page names a control per key so the values are editable.
"""

import json
import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

CONFIG_DIR = os.path.join(ROOT, "python", "input_methods")
CONFIG_HT = os.path.join(ROOT, "python", "cinbase", "config", "config.htm")

IME_DIRS = tuple(sorted(
    name for name in os.listdir(CONFIG_DIR)
    if os.path.isfile(os.path.join(CONFIG_DIR, name, "config", "config.json"))
))

COLOR_KEYS = ("candTextColor", "windowBackgroundColor", "selKeyColor")
SYSTEM_PALETTE = 0  # the "follow GetSysColor" sentinel


def fresh_config():
    from cinbase.config import CinBaseConfigClass
    return CinBaseConfigClass()


class CinbaseColorQuartetTests(unittest.TestCase):

    def shipped(self, ime):
        path = os.path.join(CONFIG_DIR, ime, "config", "config.json")
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)

    def test_defaults_exist_without_any_json(self):
        cfg = fresh_config()
        for key in COLOR_KEYS:
            self.assertIn(key, cfg.__dict__, f"{key} missing from __init__")
            self.assertEqual(SYSTEM_PALETTE, getattr(cfg, key),
                             f"{key}: default must mean the system palette")

    def test_all_shipped_defaults_carry_the_keys(self):
        self.assertEqual(9, len(IME_DIRS),
                         "the discovery must reach every shipped config.json")
        for ime in IME_DIRS:
            shipped = self.shipped(ime)
            for key in COLOR_KEYS:
                self.assertIn(key, shipped, f"{ime}: shipped default lacks {key}")
                self.assertEqual(SYSTEM_PALETTE, shipped[key],
                                 f"{ime}: {key} must ship the system-palette default")

    def test_configured_colors_are_honored(self):
        cfg = fresh_config()
        cfg.candTextColor = 0x123456
        cfg.windowBackgroundColor = 0xFFFFFF
        cfg.selKeyColor = 0x0000FF
        cfg.sanitize()
        self.assertEqual(0x123456, cfg.candTextColor)
        self.assertEqual(0xFFFFFF, cfg.windowBackgroundColor)
        self.assertEqual(0x0000FF, cfg.selKeyColor)

    def test_absent_or_bad_values_fall_back_to_the_sentinel(self):
        cfg = fresh_config()
        cfg.candTextColor = "abc"
        cfg.windowBackgroundColor = 0x1000000  # past the 24-bit range
        cfg.selKeyColor = None
        cfg.sanitize()
        self.assertEqual(SYSTEM_PALETTE, cfg.candTextColor)
        self.assertEqual(SYSTEM_PALETTE, cfg.windowBackgroundColor)
        self.assertEqual(SYSTEM_PALETTE, cfg.selKeyColor)

        # numeric strings from the settings page survive sanitizing
        cfg.candTextColor = "255"
        cfg.sanitize()
        self.assertEqual(255, cfg.candTextColor)


class CinbaseColorReadSiteTests(CinbaseKeyHarness):

    def test_the_engine_puts_the_three_colors_on_customize_ui(self):
        service = self.activate_chesimplex()
        ui = service.currentReply["customizeUI"]
        for key in COLOR_KEYS:
            self.assertIn(key, ui, f"{key} never reached the customizeUI reply")
            self.assertEqual(SYSTEM_PALETTE, ui[key])

    def test_configured_colors_reach_both_windows_through_customize_ui(self):
        service = self.activate_chesimplex()
        service.cfg.candTextColor = 0x00FF00
        service.cfg.windowBackgroundColor = 0x010203
        service.cfg.selKeyColor = 0xFF0000
        service.currentReply = {}

        service.cinbase.applyConfig(service)

        ui = service.currentReply["customizeUI"]
        self.assertEqual(0x00FF00, ui["candTextColor"])
        self.assertEqual(0x010203, ui["windowBackgroundColor"])
        self.assertEqual(0xFF0000, ui["selKeyColor"])


class SettingsPageControlTests(unittest.TestCase):

    def test_the_settings_page_names_a_control_per_color(self):
        with open(CONFIG_HT, "r", encoding="utf-8") as handle:
            page = handle.read()
        for key in COLOR_KEYS:
            self.assertIn(f'id="{key}"', page, f"{key}: no control on the page")
            self.assertIn(f'name="{key}"', page, f"{key}: control is not saved")


if __name__ == "__main__":
    unittest.main()
